import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

_cuda_src = r"""
#include <torch/extension.h>
#include <ATen/cuda/CUDAContext.h>
#include <c10/cuda/CUDAException.h>
#include <cuda_runtime.h>

// Phase 1: split each row across many blocks along N. The profiler showed
// the previous launch used only 16 blocks (one per row) on a 128-SM device,
// so the reduction over the huge normalized dim is now distributed across
// a 2D grid: blockIdx.x = row, blockIdx.y = slice. Each block reduces its
// slice in double precision and atomically accumulates per-row partials.
__global__ void layernorm_partial_reduce_kernel(
    const float* __restrict__ x,
    double* __restrict__ rowsum,
    double* __restrict__ rowsumsq,
    const long long N,
    const long long slice_len) {
  const long long row = blockIdx.x;
  const long long start = (long long)blockIdx.y * slice_len;
  long long end = start + slice_len;
  if (end > N) end = N;
  if (start >= end) return;
  const int tid = threadIdx.x;
  const int nthreads = blockDim.x;
  const float* xrow = x + row * N;
  double sum = 0.0;
  double sumsq = 0.0;
  const long long vec_end = end & ~3LL;  // start stays 16B aligned (slice_len % 4 == 0)
  const float4* x4 = reinterpret_cast<const float4*>(xrow);
  const long long vbegin = start >> 2;
  const long long vend = vec_end >> 2;
  for (long long i = vbegin + tid; i < vend; i += nthreads) {
    const float4 v = x4[i];
    sum += (double)v.x + (double)v.y + (double)v.z + (double)v.w;
    sumsq += (double)v.x * (double)v.x + (double)v.y * (double)v.y +
             (double)v.z * (double)v.z + (double)v.w * (double)v.w;
  }
  for (long long i = vec_end + tid; i < end; i += nthreads) {
    const float v = xrow[i];
    sum += (double)v;
    sumsq += (double)v * (double)v;
  }
  const int lane = tid & 31;
  const int warp = tid >> 5;
  const int nwarps = (nthreads + 31) >> 5;
  for (int offset = 16; offset > 0; offset >>= 1) {
    sum += __shfl_down_sync(0xffffffffu, sum, offset);
    sumsq += __shfl_down_sync(0xffffffffu, sumsq, offset);
  }
  __shared__ double ssum[32];
  __shared__ double ssq[32];
  if (lane == 0) {
    ssum[warp] = sum;
    ssq[warp] = sumsq;
  }
  __syncthreads();
  if (warp == 0) {
    double tsum = (lane < nwarps) ? ssum[lane] : 0.0;
    double tsq = (lane < nwarps) ? ssq[lane] : 0.0;
    for (int offset = 16; offset > 0; offset >>= 1) {
      tsum += __shfl_down_sync(0xffffffffu, tsum, offset);
      tsq += __shfl_down_sync(0xffffffffu, tsq, offset);
    }
    if (lane == 0) {
      atomicAdd(&rowsum[row], tsum);
      atomicAdd(&rowsumsq[row], tsq);
    }
  }
}
// Phase 2: normalization with a 2D grid (blockIdx.y = row, blockIdx.x =
// column slice). The previous flat grid-stride loop paid a 64-bit div/mod
// plus double-precision mean/var/rstd recomputation for every element;
// now each block gets its row for free, computes the row statistics once,
// and sweeps its slice with aligned float4 accesses and zero divisions.
__global__ void layernorm_normalize_kernel(
    const float* __restrict__ x,
    const float* __restrict__ w,
    const float* __restrict__ b,
    const double* __restrict__ rowsum,
    const double* __restrict__ rowsumsq,
    float* __restrict__ y,
    const long long N,
    const long long slice_len,
    const float eps) {
  const long long row = blockIdx.y;
  const double mean = rowsum[row] / (double)N;
  double var = rowsumsq[row] / (double)N - mean * mean;
  if (var < 0.0) var = 0.0;
  const float meanf = (float)mean;
  const float rstd = rsqrtf((float)var + eps);
  const long long start = (long long)blockIdx.x * slice_len;
  long long end = start + slice_len;
  if (end > N) end = N;
  if (start >= end) return;
  const float* xrow = x + row * N;
  float* yrow = y + row * N;
  const int tid = threadIdx.x;
  const int nthreads = blockDim.x;
  if ((N & 3LL) == 0LL) {
    // N % 4 == 0 keeps every row base 16B aligned, so float4 is safe.
    const long long vec_end = end & ~3LL;  // slice starts stay 16B aligned (slice_len % 4 == 0)
    const float4* x4 = reinterpret_cast<const float4*>(xrow);
    const float4* w4 = reinterpret_cast<const float4*>(w);
    const float4* b4 = reinterpret_cast<const float4*>(b);
    float4* y4 = reinterpret_cast<float4*>(yrow);
    const long long vbegin = start >> 2;
    const long long vend = vec_end >> 2;
    for (long long i = vbegin + tid; i < vend; i += nthreads) {
      const float4 xv = x4[i];
      const float4 wv = w4[i];
      const float4 bv = b4[i];
      float4 out;
      out.x = (xv.x - meanf) * rstd * wv.x + bv.x;
      out.y = (xv.y - meanf) * rstd * wv.y + bv.y;
      out.z = (xv.z - meanf) * rstd * wv.z + bv.z;
      out.w = (xv.w - meanf) * rstd * wv.w + bv.w;
      y4[i] = out;
    }
    for (long long i = vec_end + tid; i < end; i += nthreads) {
      yrow[i] = (xrow[i] - meanf) * rstd * w[i] + b[i];
    }
  } else {
    for (long long i = start + tid; i < end; i += nthreads) {
      yrow[i] = (xrow[i] - meanf) * rstd * w[i] + b[i];
    }
  }
}

torch::Tensor layernorm_cuda(torch::Tensor x, torch::Tensor weight, torch::Tensor bias, double eps) {
  TORCH_CHECK(x.is_cuda(), "x must be CUDA");
  TORCH_CHECK(weight.is_cuda() && bias.is_cuda(), "weight/bias must be CUDA");
  TORCH_CHECK(x.scalar_type() == at::kFloat, "x must be float32");
  TORCH_CHECK(weight.scalar_type() == at::kFloat && bias.scalar_type() == at::kFloat,
              "weight/bias must be float32");

  auto xc = x.contiguous();
  auto wc = weight.contiguous();
  auto bc = bias.contiguous();

  const long long N = (long long)wc.numel();
  TORCH_CHECK(N > 0, "normalized_shape numel must be positive");
  TORCH_CHECK(xc.numel() % N == 0, "input trailing dims must match normalized_shape");
  const long long rows = (long long)xc.numel() / N;

  auto y = at::empty_like(xc);
  if (rows == 0) return y;

  auto stream = at::cuda::getCurrentCUDAStream();
  const int num_sms = at::cuda::getCurrentDeviceProperties()->multiProcessorCount;
  auto opts = xc.options().dtype(at::kDouble);
  auto rowsum = at::zeros({rows}, opts);
  auto rowsumsq = at::zeros({rows}, opts);
  dim3 rblock(256);
  long long slices = ((long long)num_sms * 8LL + rows - 1LL) / rows;
  long long slice_len = (N + slices - 1LL) / slices;
  slice_len = (slice_len + 3LL) & ~3LL;  // keep 16B alignment of slice starts
  slices = (N + slice_len - 1LL) / slice_len;
  if (slices < 1) slices = 1;
  dim3 rgrid((unsigned int)rows, (unsigned int)slices);
  layernorm_partial_reduce_kernel<<<rgrid, rblock, 0, stream>>>(
      xc.data_ptr<float>(),
      rowsum.data_ptr<double>(),
      rowsumsq.data_ptr<double>(),
      N,
      slice_len);
  C10_CUDA_KERNEL_LAUNCH_CHECK();
  dim3 nblock(256);
  long long nslices = ((long long)num_sms * 8LL + rows - 1LL) / rows;
  long long nslice_len = (N + nslices - 1LL) / nslices;
  nslice_len = (nslice_len + 3LL) & ~3LL;  // keep 16B alignment of slice starts
  nslices = (N + nslice_len - 1LL) / nslice_len;
  if (nslices < 1) nslices = 1;
  dim3 ngrid((unsigned int)nslices, (unsigned int)rows);
  layernorm_normalize_kernel<<<ngrid, nblock, 0, stream>>>(
      xc.data_ptr<float>(),
      wc.data_ptr<float>(),
      bc.data_ptr<float>(),
      rowsum.data_ptr<double>(),
      rowsumsq.data_ptr<double>(),
      y.data_ptr<float>(),
      N,
      nslice_len,
      (float)eps);
  C10_CUDA_KERNEL_LAUNCH_CHECK();
  return y;
}
"""

_cpp_src = "torch::Tensor layernorm_cuda(torch::Tensor x, torch::Tensor weight, torch::Tensor bias, double eps);"

_layernorm_ext = load_inline(
    name="custom_layernorm_ext",
    cpp_sources=_cpp_src,
    cuda_sources=_cuda_src,
    functions=["layernorm_cuda"],
    extra_cflags=["-O3"],
    extra_cuda_cflags=["-O3"],
    verbose=False,
)


class ModelNew(nn.Module):
    def __init__(self, normalized_shape: tuple):
        super().__init__()
        self.normalized_shape = tuple(normalized_shape)
        self.eps = 1e-5
        self.weight = nn.Parameter(torch.ones(self.normalized_shape))
        self.bias = nn.Parameter(torch.zeros(self.normalized_shape))

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return _layernorm_ext.layernorm_cuda(x, self.weight, self.bias, self.eps)

